// draw-on: el = <path> SVG com stroke
const path = el;
const L = path.getTotalLength();
tl.fromTo(path, { strokeDasharray: L, strokeDashoffset: L }, { strokeDashoffset: 0, duration: 1.0, ease: "power2.inOut" }, t);

// morph sem plugin: mesmo elemento muda raio + escala + cor
const A = "#1F6FEB", B = "#D0592C";
tl.fromTo(el, { borderRadius: "50%", scale: 1, backgroundColor: A },
  { borderRadius: "16%", scale: 1.15, backgroundColor: B, duration: 0.6, ease: "power3.inOut" }, t);
// paths SVG arbitrários: MorphSVGPlugin -> tl.fromTo(el, { morphSVG: el }, { morphSVG: "#alvo", duration: 0.6, ease: "power3.inOut" }, t);

// a = haste (<path>), b = ponta (<path> separada, origem no centro)
const shaft = a, head = b, L = shaft.getTotalLength();
tl.fromTo(shaft, { strokeDasharray: L, strokeDashoffset: L }, { strokeDashoffset: 0, duration: 0.6, ease: "power2.inOut" }, t);
tl.fromTo(head, { scale: 0, opacity: 0, transformOrigin: "50% 50%" }, { scale: 1, opacity: 1, duration: 0.25, ease: "back.out(2.5)" }, t + 0.55);

// MorphSVGPlugin: três formas orgânicas fixas (#blob1..3) no <defs>; loop finito
const shapes = ["#blob2", "#blob3", "#blob1"], cycle = 1.4, sceneDur = 4.2;
const n = Math.floor(sceneDur / cycle);
const bb = el.getBBox(), origin = bb.x + bb.width / 2 + " " + (bb.y + bb.height / 2); // pivô fixo: a forma muda, o centro não
tl.set(el, { morphSVG: "#blob1" }, t);
for (let k = 0; k < n; k++) tl.to(el, { morphSVG: shapes[k % 3], duration: cycle, ease: "sine.inOut" }, t + k * cycle);
tl.fromTo(el, { rotation: 0, svgOrigin: origin }, { rotation: 40, duration: n * cycle, ease: "none" }, t);

// DrawSVGPlugin: a = anel, b = check, el = selo inteiro
const ring = a, check = b;
tl.fromTo(ring, { drawSVG: "0%", rotation: -90, transformOrigin: "50% 50%" }, { drawSVG: "100%", duration: 0.5, ease: "power2.inOut" }, t);
tl.fromTo(check, { drawSVG: "0%" }, { drawSVG: "100%", duration: 0.3, ease: "power3.out" }, t + 0.4);
tl.fromTo(el, { scale: 1 }, { keyframes: { scale: [1, 1.12, 1] }, duration: 0.3, ease: "none" }, t + 0.7);

// items = 4 cantos em L (sup-esq, sup-dir, inf-esq, inf-dir)
const off = [[-60, -60], [60, -60], [-60, 60], [60, 60]];
items.forEach((c, i) => tl.fromTo(c, { x: off[i][0], y: off[i][1], opacity: 0 }, { x: 0, y: 0, opacity: 1, duration: 0.45, ease: "power3.out" }, t + i * 0.03));

// path com stroke-dasharray: 16 12 no CSS; cada ciclo anda um padrão (28 px)
const sceneDur = 3, cycle = 0.6, n = Math.floor(sceneDur / cycle);
tl.fromTo(el, { strokeDashoffset: 0 }, { strokeDashoffset: -28 * n, duration: cycle * n, ease: "none" }, t);

// el = linha de 720x12 px; clip-path deixa ver só o ponto central
tl.fromTo(el, { scale: 0, clipPath: "inset(0px 354px 0px 354px round 6px)" }, { scale: 1, duration: 0.25, ease: "back.out(2)" }, t);
tl.fromTo(el, { clipPath: "inset(0px 354px 0px 354px round 6px)" }, { clipPath: "inset(0px 0px 0px 0px round 6px)", duration: 0.5, ease: "expo.inOut", immediateRender: false }, t + 0.3);

// items = [nóA, nóB]; el = linha já rotacionada de A até B
const [nA, nB] = items, line = el;
tl.fromTo(nA, { scale: 0 }, { scale: 1, duration: 0.3, ease: "back.out(1.7)" }, t);
tl.fromTo(line, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.5, ease: "power2.inOut" }, t + 0.2);
tl.fromTo(nB, { scale: 0 }, { scale: 1, duration: 0.3, ease: "back.out(1.7)" }, t + 0.6);

// MorphSVGPlugin: a mesma <path> começa reta e se fecha em #forma
const L = el.getTotalLength();
tl.fromTo(el, { strokeDasharray: L, strokeDashoffset: L }, { strokeDashoffset: 0, duration: 0.5, ease: "power2.out" }, t);
tl.set(el, { strokeDasharray: "none" }, t + 0.5);
tl.fromTo(el, { morphSVG: el }, { morphSVG: "#forma", duration: 0.7, ease: "power3.inOut", immediateRender: false }, t + 0.5);

// container com clip-path da forma; el = líquido, a = faixa de onda (2x a largura)
const liquid = el, wave = a, level = 0.7; // 70% cheio
tl.fromTo(liquid, { yPercent: 100 }, { yPercent: 100 - level * 100, duration: 1.4, ease: "power2.out" }, t);
// onda: anda um período (540 px) a cada 0.8 s, 3 ciclos
tl.fromTo(wave, { x: 0 }, { x: -540 * 3, duration: 0.8 * 3, ease: "none" }, t);

// DrawSVGPlugin: arco gira e respira; voltas finitas calculadas pela espera
const wait = 2.4, turn = 0.8, n = Math.round(wait / turn);
tl.fromTo(el, { rotation: 0, transformOrigin: "50% 50%" }, { rotation: 360 * n, duration: wait, ease: "none" }, t);
tl.fromTo(el, { drawSVG: "0% 10%" }, { drawSVG: "0% 70%", duration: turn / 2, ease: "sine.inOut", yoyo: true, repeat: n * 2 - 1 }, t);
tl.fromTo(el, { opacity: 1, scale: 1 }, { opacity: 0, scale: 0.6, duration: 0.25, ease: "power2.in", immediateRender: false }, t + wait);

// MotionPathPlugin: el percorre o <path id="rota"> girando com a curva
const route = scene.querySelector("#rota");
tl.set(el, { x: 0, y: 0, rotation: 0 }, t);
tl.to(el, { motionPath: { path: route, align: route, alignOrigin: [0.5, 0.5], autoRotate: true }, duration: 1.6, ease: "power1.inOut" }, t);

// MorphSVGPlugin: el passa por polígonos fixos, 60° por troca
const seq = ["#quad", "#hex", "#tri"], step = 0.45, gap = 0.15;
tl.set(el, { morphSVG: "#tri", rotation: 0, transformOrigin: "50% 50%" }, t);
seq.forEach((s, k) => tl.to(el, { morphSVG: s, rotation: 60 * (k + 1), duration: step, ease: "power3.inOut" }, t + k * (step + gap)));

// items = 8 formas empilhadas no centro; ângulos fixos, distância alternada
items.forEach((s, i) => {
  const ang = (i / items.length) * Math.PI * 2, d = i % 2 ? 260 : 340;
  tl.fromTo(s, { x: 0, y: 0, rotation: 0 }, { x: Math.cos(ang) * d, y: Math.sin(ang) * d, rotation: 90 + i * 25, duration: 0.6, ease: "power3.out" }, t);
  // escala e opacidade num tween só: dois tweens disputando scale no mesmo trecho não são seek-safe
  tl.fromTo(s, { scale: 0, opacity: 1 }, { keyframes: [{ scale: 1, duration: 0.45, ease: "power3.out" }, { scale: 0.4, opacity: 0, duration: 0.3, ease: "power2.in" }] }, t);
});

// DrawSVGPlugin: items = 12 raios <line> do centro para fora; el = objeto central
tl.fromTo(items, { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 0.25, ease: "power2.out", stagger: 0.015 }, t);
tl.fromTo(items, { drawSVG: "0% 100%" }, { drawSVG: "100% 100%", duration: 0.3, ease: "power2.in", stagger: 0.015, immediateRender: false }, t + 0.25);
tl.fromTo(el, { scale: 0.6 }, { scale: 1, duration: 0.4, ease: "back.out(2)" }, t);

const L = el.getTotalLength();
tl.fromTo(el, { strokeDasharray: L, strokeDashoffset: L, fillOpacity: 0 }, { strokeDashoffset: 0, duration: 0.9, ease: "power2.inOut" }, t);
tl.fromTo(el, { fillOpacity: 0, strokeOpacity: 1 }, { fillOpacity: 1, strokeOpacity: 0, duration: 0.4, ease: "power2.out", immediateRender: false }, t + 0.8);

// el = linha absoluta sob a palavra
tl.fromTo(el, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.45, ease: "power3.out" }, t);
// saída: some para a direita com clip-path (trocar transformOrigin no meio da timeline não é seek-safe)
tl.fromTo(el, { clipPath: "inset(0% 0% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 100%)", duration: 0.35, ease: "power3.in", immediateRender: false }, t + 1.6);

// DrawSVGPlugin: items = [traço1, traço2]; el = grupo do X
const [s1, s2] = items;
tl.fromTo(s1, { drawSVG: "0%" }, { drawSVG: "100%", duration: 0.18, ease: "power2.in" }, t);
tl.fromTo(s2, { drawSVG: "0%" }, { drawSVG: "100%", duration: 0.18, ease: "power2.in" }, t + 0.14);
tl.fromTo(el, { x: 0 }, { keyframes: { x: [0, -10, 8, -5, 3, 0] }, duration: 0.3, ease: "none" }, t + 0.32);
